parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "repositories": {
      "type": "array",
      "description": "Summaries for all repositories provided in the input.",
      "items": {
        "type": "object",
        "properties": {
          "url": {
            "type": "string",
            "description": "The exact GitHub repository URL provided in the input. Do not modify or shorten it."
          },
          "summary": {
            "type": "string",
            "description": "One concise sentence explaining what the repository does."
          },
          "why_it_matters": {
            "type": "string",
            "description": "Brief explanation of why developers might care about this repository."
          },
          "best_for": {
            "type": "string",
            "description": "Who this repository is most useful for."
          },
          "keywords": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Three to five short technical keywords or tags."
          }
        },
        "required": ["url", "summary", "why_it_matters", "best_for", "keywords"]
      }
    }
  },
  "required": ["repositories"]
}

parameters.jsCode:
const nRepos = $('Set Digest Config').first().json.n_repos ?? 5;

return $input
  .all()
  .slice(0, nRepos);

const readmeItems = $input.all();
const originalItems = $('Limit Repositories').all();

const repositories = readmeItems.map((item, index) => {
  const original = originalItems[index]?.json ?? {};
  const readmeResponse = item.json;

  let readmeText = "README not available.";

  if (readmeResponse.content) {
    readmeText = Buffer
      .from(readmeResponse.content.replace(/\n/g, ""), "base64")
      .toString("utf8");
  }

  return {
    url: original.url,
    readmeText: readmeText.slice(0, 8000)
  };
});

return [
  {
    json: {
      repositories
    }
  }
];

const repos = $json.output.repositories;

function repoNameFromUrl(url) {
  return url.replace("https://github.com/", "");
}

function pickEmoji(keywords = []) {
  const text = keywords.join(" ").toLowerCase();

  if (text.includes("ai") || text.includes("llm") || text.includes("agent")) return "🤖";
  if (text.includes("finance") || text.includes("trading")) return "💸";
  if (text.includes("developer") || text.includes("coding") || text.includes("software")) return "🧑‍💻";
  if (text.includes("terminal") || text.includes("cli") || text.includes("tui")) return "⌨️";
  if (text.includes("performance") || text.includes("optimization") || text.includes("inference")) return "⚡";
  if (text.includes("security")) return "🛡️";

  return "🚀";
}

const today = new Date().toISOString().slice(0, 10);

const blocks = repos.map((repo, index) => {
  const name = repoNameFromUrl(repo.url);
  const keywords = repo.keywords.map(k => `#${k.replace(/\s+/g, "")}`).join(" ");
  const emoji = pickEmoji(repo.keywords);

  return [
    `${emoji} *${index + 1}. [${name}](${repo.url})*`,
    `🧩 *What it is:* ${repo.summary}`,
    `✨ *Why it matters:* ${repo.why_it_matters}`,
    `🎯 *Best for:* ${repo.best_for}`,
    `🏷️ ${keywords}`
  ].join("\n");
});

const message = [
  "🔥 *Daily GitHub Trending AI Digest*",
  `📅 ${today}`,
  "Fresh repos worth a quick look today:",
  "",
  blocks.join("\n\n"),
  "",
  "—",
  "_Generated from GitHub Trending READMEs using AI._"
].join("\n");

return [
  {
    json: {
      telegramMessage: message
    }
  }
];
